{"action":"write_file","path":"emitter.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { Emitter } = require('./emitter');

test('listeners run in registration order with the arguments', () => {
  const e = new Emitter();
  const seen = [];
  e.on('x', (a, b) => seen.push(['first', a, b]));
  e.on('x', (a) => seen.push(['second', a]));
  assert.equal(e.emit('x', 1, 2), true);
  assert.deepEqual(seen, [['first', 1, 2], ['second', 1]]);
});

test('once runs one time', () => {
  const e = new Emitter();
  let n = 0;
  e.once('x', () => n++);
  e.emit('x');
  e.emit('x');
  assert.equal(n, 1);
});

test('emit reports whether anyone listened', () => {
  assert.equal(new Emitter().emit('nobody'), false);
});

test('off removes earliest registration and returns boolean', () => {
  const e = new Emitter();
  const fn = () => {};
  e.on('x', fn);
  e.on('x', fn);
  assert.equal(e.listenerCount('x'), 2);
  assert.equal(e.off('x', fn), true);
  assert.equal(e.listenerCount('x'), 1);
  assert.equal(e.off('x', fn), true);
  assert.equal(e.listenerCount('x'), 0);
  assert.equal(e.off('x', fn), false);
});

test('unsubscribe function returned by on/once removes registration', () => {
  const e = new Emitter();
  let count = 0;
  const unsub = e.on('x', () => count++);
  e.emit('x');
  assert.equal(count, 1);
  unsub();
  e.emit('x');
  assert.equal(count, 1);
  unsub(); // calling again does nothing
});

test('type validation for event and listener', () => {
  const e = new Emitter();
  assert.throws(() => e.on(123, () => {}), TypeError);
  assert.throws(() => e.on('x', 'not a func'), TypeError);
  assert.throws(() => e.once(123, () => {}), TypeError);
  assert.throws(() => e.once('x', null), TypeError);
  assert.throws(() => e.off(123, () => {}), TypeError);
  assert.throws(() => e.off('x', {}), TypeError);
  assert.throws(() => e.listenerCount(123), TypeError);
});

test('listener throwing propagates error and stops remaining listeners', () => {
  const e = new Emitter();
  const seen = [];
  e.on('x', () => seen.push(1));
  e.on('x', () => {
    seen.push(2);
    throw new Error('boom');
  });
  e.on('x', () => seen.push(3));

  assert.throws(() => e.emit('x'), /boom/);
  assert.deepEqual(seen, [1, 2]);
});

test('listener added or removed during emit behave correctly', () => {
  const e = new Emitter();
  const seen = [];

  const l2 = () => seen.push('l2');
  const unsub1 = e.on('x', () => {
    seen.push('l1');
    e.on('x', () => seen.push('l3')); // added during emit, shouldn't run this time
    unsub1(); // removed during emit, should still run this time
  });

  e.emit('x');
  assert.deepEqual(seen, ['l1']);

  seen.length = 0;
  e.emit('x');
  assert.deepEqual(seen, ['l3']);
});

test('once listener re-emit prevention', () => {
  const e = new Emitter();
  let count = 0;
  e.once('x', () => {
    count++;
    e.emit('x');
  });
  e.emit('x');
  assert.equal(count, 1);
});
"}
